const MARKUP="<main class=\"wrap\">\n<header class=\"hero\"><h1>Belavadós World Forge</h1><p>All-in-one settlement, visitable location, and NPC generator · race-aware · biome-aware · Emperor Onyx integrated.</p><div class=\"stats\"><div class=\"stat\"><strong id=\"locCount\">0</strong>Locations</div><div class=\"stat\"><strong id=\"npcCount\">0</strong>NPCs</div><div class=\"stat\"><strong id=\"assetCount\">0</strong>Imported files</div><div class=\"stat\"><strong id=\"validCount\">0</strong>Biome checks passed</div></div>\n<div class=\"row\"><button class=\"btn\" onclick=\"document.getElementById('files').click()\">Import any files / ZIP</button><input hidden=\"\" id=\"files\" multiple=\"\" type=\"file\"/><button class=\"btn\" onclick=\"exportJSON()\">Export JSON</button><button class=\"btn\" onclick=\"exportHTML()\">Export HTML</button><button class=\"btn\" onclick=\"exportDOCX()\">Export DOCX</button><button class=\"btn\" onclick=\"saveLocal()\">Save locally</button><button class=\"btn\" onclick=\"loadLocal()\">Load saved</button></div><p class=\"muted\">Imports accept arbitrary files for asset inventory; JSON/HTML are parsed for usable data. ZIP extraction uses JSZip when available. DOCX import is inventoried and retained as a source file; export creates a real DOCX package.</p></header>\n<nav class=\"tabs\"><button class=\"active\" data-tab=\"forge\">Generator</button><button data-tab=\"directory\">Directory &amp; Editor</button><button data-tab=\"assets\">Asset Library</button><button data-tab=\"rules\">Rules &amp; QA</button></nav>\n<section class=\"section active\" id=\"forge\"><div class=\"panel\"><h2>World and settlement setup</h2><div class=\"grid\">\n<div><label>Settlement name</label><input id=\"settlementName\" value=\"New Settlement\"/></div><div><label>Settlement size</label><select id=\"size\"><option>Village</option><option>Town</option><option>City</option><option>Capital City</option></select></div><div><label>Government</label><input id=\"government\" value=\"Local Council\"/></div>\n<div><label>Province</label><input id=\"province\" value=\"Unassigned Province\"/></div><div><label>Population target (NPCs)</label><input id=\"population\" min=\"1\" type=\"number\" value=\"800\"/></div><div><label>Generate locations</label><input id=\"locationTarget\" min=\"1\" type=\"number\" value=\"60\"/></div>\n<div><label>People category (menu 1)</label><select id=\"raceCategory\"></select></div><div><label>Species / approved heritage (menu 2)</label><select disabled=\"\" id=\"raceChoice\"><option>Select a category first</option></select></div><div><label>Habitat preference</label><select id=\"raceHabitat\"></select></div>\n<div><label>Biome family (menu 1)</label><select id=\"biomeFamily\"></select></div><div><label>Biome subtype (menu 2)</label><select disabled=\"\" id=\"biomeSubtype\"></select></div><div><label>Climate / notes</label><input id=\"climate\" placeholder=\"e.g. cold, temperate, humid\"/></div>\n<div><label>Primary religion</label><select id=\"religion\"></select></div><div><label>Culture</label><input id=\"culture\" value=\"Belavadós local culture\"/></div><div><label>Population race share (%)</label><input id=\"raceShare\" max=\"100\" min=\"1\" type=\"number\" value=\"25\"/></div>\n</div><div class=\"row\"><button class=\"btn\" onclick=\"generateSettlement()\">Generate settlement + NPCs</button><button class=\"btn\" onclick=\"generateNPCs(10)\">Add 10 NPCs</button><button class=\"btn\" onclick=\"generateLocations(10)\">Add 10 locations</button><button class=\"btn\" onclick=\"checkBiome()\">Run biome validation</button></div><p class=\"muted\" id=\"validation\">Choose a biome to enable habitat-aware location generation.</p></div>\n<div class=\"panel\"><h2>Generated location pins</h2><p class=\"muted\">Select a pin/location to edit details. Pin colors follow the supplied master hierarchy; invalid environment combinations are blocked or flagged.</p><div class=\"list\" id=\"locations\"></div></div><div class=\"panel\"><h2>NPC population</h2><input id=\"npcSearch\" oninput=\"renderNPCs()\" placeholder=\"Search NPCs by name, profession, race…\"/><div class=\"list\" id=\"npcs\"></div></div></section>\n<section class=\"section\" id=\"directory\"><div class=\"panel\"><h2>Settlement directory</h2><div class=\"grid two\"><div><label>Search</label><input id=\"dirSearch\" oninput=\"renderDirectory()\" placeholder=\"Settlement, province, government…\"/></div><div><label>Sort</label><select id=\"dirSort\" onchange=\"renderDirectory()\"><option value=\"name\">Name</option><option value=\"population\">Population</option><option value=\"locations\">Location count</option></select></div></div><div class=\"list\" id=\"directoryList\"></div></div><div class=\"panel\"><h2>Edit selected settlement</h2><div id=\"editor\">Generate or import a settlement to begin.</div></div></section>\n<section class=\"section\" id=\"assets\"><div class=\"panel\"><h2>Asset uploader &amp; manifest</h2><p>Drag files here or use Import. Files are listed by type, size, and duplicate hash. Browser security means files are not silently written to your folders; download exports to save them.</p><div id=\"dropzone\" style=\"border:2px dashed #37677b;padding:25px;text-align:center;border-radius:12px\">Drop files here</div><div class=\"row\"><button class=\"btn\" onclick=\"exportManifest()\">Export asset manifest JSON</button><button class=\"btn\" onclick=\"clearAssets()\">Clear asset list</button></div><div class=\"list\" id=\"assetList\"></div></div></section>\n<section class=\"section\" id=\"rules\"><div class=\"panel\"><h2>Biome rules &amp; transportation</h2><p>Biome compatibility is rule-based, explainable, and editable in the generated data. Rare magical exceptions can be recorded in location notes.</p><div id=\"ruleSummary\"></div><h3>QA / current validation</h3><div id=\"qa\"></div><p class=\"muted\">This is a client-side static app. Browser-specific, scale, security, and integration testing must be performed in the target hosting environment; this package does not claim that unrun tests have passed.</p></div></section>\n</main>\n\n\n\n<style>:root {\n  --onyx-bg: rgba(8, 7, 10, 0.95);\n  --onyx-panel: rgba(24, 20, 28, 0.97);\n  --onyx-ink: #f6efe5;\n  --onyx-muted: #b8a995;\n  --onyx-gold: #d9a441;\n  --onyx-red: #8d2b2f;\n  --onyx-purple: #4d365f;\n  --onyx-green: #89a46f;\n  --onyx-border: rgba(217, 164, 65, 0.42);\n  --onyx-shadow: 0 18px 50px rgba(0, 0, 0, 0.5);\n  --onyx-radius: 18px;\n  --onyx-font: Georgia, \"Times New Roman\", serif;\n  --onyx-ui-font: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n#emperor-onyx-root, #emperor-onyx-root * {\n  box-sizing: border-box;\n}\n\n#emperor-onyx-root {\n  position: fixed;\n  right: 22px;\n  bottom: 22px;\n  z-index: 999999;\n  color: var(--onyx-ink);\n  font-family: var(--onyx-ui-font);\n}\n\n.onyx-launcher {\n  border: 1px solid var(--onyx-border);\n  background: radial-gradient(circle at 30% 20%, rgba(217,164,65,.22), rgba(0,0,0,.92) 52%), #050407;\n  color: var(--onyx-ink);\n  min-width: 72px;\n  min-height: 72px;\n  border-radius: 999px;\n  box-shadow: var(--onyx-shadow);\n  cursor: pointer;\n  display: grid;\n  place-items: center;\n  position: relative;\n  overflow: hidden;\n}\n\n.onyx-launcher:hover { transform: translateY(-1px); }\n.onyx-launcher:focus-visible { outline: 3px solid var(--onyx-gold); outline-offset: 3px; }\n\n.onyx-cat-face {\n  font-size: 34px;\n  filter: drop-shadow(0 2px 6px rgba(217, 164, 65, .5));\n}\n\n.onyx-badge {\n  position: absolute;\n  right: 6px;\n  top: 6px;\n  background: var(--onyx-red);\n  color: white;\n  border: 1px solid rgba(255,255,255,.35);\n  width: 22px;\n  height: 22px;\n  display: grid;\n  place-items: center;\n  border-radius: 50%;\n  font-size: 12px;\n  font-weight: 800;\n}\n\n.onyx-shell {\n  width: min(440px, calc(100vw - 24px));\n  height: min(680px, calc(100vh - 24px));\n  background: linear-gradient(180deg, rgba(32, 26, 38, .98), rgba(8, 7, 10, .98));\n  border: 1px solid var(--onyx-border);\n  border-radius: var(--onyx-radius);\n  box-shadow: var(--onyx-shadow);\n  overflow: hidden;\n  display: none;\n}\n\n.onyx-shell.onyx-open { display: grid; grid-template-rows: auto 1fr auto; }\n\n.onyx-header {\n  display: grid;\n  grid-template-columns: auto 1fr auto auto;\n  gap: 10px;\n  align-items: center;\n  padding: 12px 12px 10px;\n  border-bottom: 1px solid var(--onyx-border);\n  background: linear-gradient(90deg, rgba(141, 43, 47, .28), rgba(77, 54, 95, .28));\n}\n\n.onyx-avatar {\n  width: 44px;\n  height: 44px;\n  border-radius: 50%;\n  display: grid;\n  place-items: center;\n  background: #050407;\n  border: 1px solid var(--onyx-border);\n  font-size: 24px;\n}\n\n.onyx-title { line-height: 1.15; }\n.onyx-title strong { display: block; font-family: var(--onyx-font); letter-spacing: .03em; font-size: 18px; }\n.onyx-title span { color: var(--onyx-muted); font-size: 12px; }\n\n.onyx-icon-button, .onyx-small-button, .onyx-send, .onyx-chip, .onyx-tab {\n  border: 1px solid var(--onyx-border);\n  background: rgba(255,255,255,.05);\n  color: var(--onyx-ink);\n  border-radius: 10px;\n  cursor: pointer;\n}\n\n.onyx-icon-button { width: 34px; height: 34px; font-weight: 800; }\n.onyx-icon-button:hover, .onyx-small-button:hover, .onyx-send:hover, .onyx-chip:hover, .onyx-tab:hover { background: rgba(217,164,65,.14); }\n\n.onyx-tabs {\n  display: flex;\n  gap: 8px;\n  padding: 9px 12px;\n  overflow-x: auto;\n  border-bottom: 1px solid rgba(217,164,65,.2);\n}\n\n.onyx-tab {\n  font-size: 12px;\n  padding: 7px 10px;\n  white-space: nowrap;\n}\n.onyx-tab[aria-selected=\"true\"] { background: rgba(217,164,65,.2); }\n\n.onyx-body {\n  overflow: auto;\n  padding: 12px;\n  background-image: radial-gradient(circle at 16% 10%, rgba(217,164,65,.07), transparent 28%);\n}\n\n.onyx-message {\n  border: 1px solid rgba(217,164,65,.2);\n  background: rgba(0,0,0,.25);\n  border-radius: 14px;\n  padding: 10px 11px;\n  margin: 0 0 10px;\n  line-height: 1.45;\n  font-size: 14px;\n  white-space: pre-wrap;\n}\n\n.onyx-message.onyx-user {\n  margin-left: 38px;\n  background: rgba(77, 54, 95, .32);\n}\n\n.onyx-message.onyx-bot {\n  margin-right: 20px;\n}\n\n.onyx-message h4 {\n  margin: 0 0 6px;\n  color: var(--onyx-gold);\n  font-family: var(--onyx-font);\n}\n\n.onyx-message table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n  margin-top: 6px;\n}\n\n.onyx-message th, .onyx-message td {\n  border: 1px solid rgba(217,164,65,.24);\n  padding: 5px;\n  vertical-align: top;\n}\n\n.onyx-message th { color: var(--onyx-gold); text-align: left; }\n\n.onyx-quickbar {\n  display: flex;\n  gap: 7px;\n  flex-wrap: wrap;\n  padding: 9px 12px 0;\n  background: rgba(0,0,0,.16);\n}\n\n.onyx-chip {\n  padding: 6px 9px;\n  font-size: 12px;\n}\n\n.onyx-input-row {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 8px;\n  padding: 10px 12px 12px;\n  border-top: 1px solid var(--onyx-border);\n  background: rgba(0,0,0,.35);\n}\n\n.onyx-input {\n  width: 100%;\n  resize: none;\n  border: 1px solid rgba(217,164,65,.35);\n  background: rgba(255,255,255,.07);\n  color: var(--onyx-ink);\n  border-radius: 12px;\n  padding: 10px;\n  min-height: 44px;\n  max-height: 120px;\n  font: inherit;\n}\n\n.onyx-input:focus { outline: 2px solid rgba(217,164,65,.45); }\n\n.onyx-send { padding: 0 14px; font-weight: 800; }\n\n.onyx-card {\n  border: 1px solid rgba(217,164,65,.26);\n  border-radius: 12px;\n  padding: 9px;\n  background: rgba(255,255,255,.045);\n  margin-top: 8px;\n}\n\n.onyx-card-title { color: var(--onyx-gold); font-weight: 800; margin-bottom: 5px; }\n.onyx-muted { color: var(--onyx-muted); }\n.onyx-danger { color: #ffb4b4; }\n.onyx-success { color: #cce8b7; }\n\n.onyx-hidden { display: none !important; }\n\n.onyx-importer {\n  border-top: 1px solid rgba(217,164,65,.22);\n  padding: 10px 12px;\n  background: rgba(0,0,0,.3);\n}\n\n.onyx-importer textarea {\n  width: 100%;\n  min-height: 100px;\n  border-radius: 10px;\n  border: 1px solid rgba(217,164,65,.35);\n  background: rgba(255,255,255,.06);\n  color: var(--onyx-ink);\n  padding: 8px;\n}\n\n.onyx-small-button { padding: 7px 9px; margin: 4px 4px 0 0; }\n\n@media (max-width: 520px) {\n  #emperor-onyx-root { right: 10px; bottom: 10px; }\n  .onyx-shell { width: calc(100vw - 20px); height: calc(100vh - 20px); }\n}\n</style>\n";
