const $=id=>document.getElementById(id);let state={settlements:[],current:null,assets:[],qa:[]};const sizeTargets={"Village":[60,800],"Town":[220,3000],"City":[1000,13500],"Capital City":[1312,17940]};
function fill(sel,items,placeholder){sel.innerHTML='';if(placeholder){let o=document.createElement('option');o.value='';o.textContent=placeholder;sel.append(o)}items.forEach(x=>{let o=document.createElement('option');o.value=x.value??x.label??x;o.textContent=x.label??x;sel.append(o)})}
fill($('raceCategory'),RACE_DATA.raceCategories.map(c=>({value:c.value,label:c.label})),'Choose race category');fill($('raceHabitat'),RACE_DATA.habitatOptions.map(x=>({value:x.value,label:x.label})));fill($('biomeFamily'),Object.keys(BIOMES),'Choose biome family');
$('raceCategory').onchange=()=>{let c=RACE_DATA.raceCategories.find(c=>c.value===$('raceCategory').value);let h=$('raceHabitat').value||'any';let races=(c?.races||[]).filter(r=>h==='any'||(r.habitats||[]).includes(h));fill($('raceChoice'),races.map(r=>({value:r.value,label:r.label})),'Choose race / bloodline');$('raceChoice').disabled=!c;};$('raceHabitat').onchange=()=>{let c=RACE_DATA.raceCategories.find(c=>c.value===$('raceCategory').value);let h=$('raceHabitat').value;let races=(c?.races||[]).filter(r=>h==='any'||(r.habitats||[]).includes(h));fill($('raceChoice'),races.map(r=>({value:r.value,label:r.label})),'Choose race / bloodline');$('raceChoice').disabled=!c;};$('biomeFamily').onchange=()=>{let b=BIOMES[$('biomeFamily').value]||[];fill($('biomeSubtype'),b,'Choose biome subtype');$('biomeSubtype').disabled=!b.length;checkBiome();};
